  font-size: 14px;
  display: flex;
  align-items: center;
  gap: 6px;
  background: linear-gradient(180deg, #fafcff 0%, #fff 100%);
}
.palette-header::before {
  content: '';
  width: 4px;
  height: 16px;
  border-radius: 2px;
  background: linear-gradient(180deg, #409EFF, #66b1ff);
}
.palette-search {
  padding: 10px 12px;
}
.palette-groups {
  flex: 1;
  overflow-y: auto;
  padding: 0 12px 12px;
}
.palette-group {
  margin-bottom: 14px;
}
.group-title {
  font-size: 12px;
