  margin-bottom: 8px;
  padding-left: 4px;
  font-weight: 600;
  letter-spacing: 0.5px;
}
.palette-node {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  margin-bottom: 6px;
  border: 1px solid #e8e8e8;
  border-radius: 8px;
  cursor: grab;
  transition: all 0.2s;
  background: #fafbfc;
  user-select: none;
}
.palette-node:hover {
  border-color: #409EFF;
  background: #f0f7ff;
  transform: translateX(3px);
  box-shadow: 0 2px 8px rgba(64, 158, 255, 0.15);
}
.palette-node:active {
  cursor: grabbing;
}
.node-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.04);
}
.node-dot.green { background: #52c41a; }
.node-dot.blue { background: #409EFF; }
.node-dot.purple { background: #722ed1; }
.node-dot.orange { background: #fa8c16; }
.node-dot.cyan { background: #13c2c2; }
.node-dot.red { background: #f5222d; }
.node-label {
  flex: 1;
  font-size: 13px;
  color: #333;
}
.node-add-icon {
  color: #bfbfbf;
  font-size: 12px;
}
.palette-node:hover .node-add-icon {
  color: #409EFF;
}

/* 中间画布 */
.canvas-wrap {
  flex: 1;
  position: relative;
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 4px 16px rgba(0, 21, 41, 0.08);
  overflow: hidden;
  min-width: 0;
}
.grid-bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image:
    linear-gradient(rgba(64, 158, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(64, 158, 255, 0.06) 1px, transparent 1px);
}
.edge-layer {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
}
.edge-path {
  fill: none;
  stroke: #409EFF;
  stroke-width: 2;
  pointer-events: stroke;
  cursor: pointer;
  filter: drop-shadow(0 1px 2px rgba(64, 158, 255, 0.2));
}
/* 加宽命中区域，便于点击连线 */
.edge-path-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  pointer-events: stroke;
  cursor: pointer;
}
.edge-path.is-selected {
  stroke: #fa8c16;
  stroke-width: 3;
  filter: drop-shadow(0 1px 3px rgba(250, 140, 22, 0.4));
}
.edge-path.is-dragging {
  stroke-dasharray: 6 4;
  stroke: #13c2c2;
}
.edge-label {
  font-size: 11px;
  fill: #fa8c16;
  font-weight: 600;
  text-anchor: middle;
  pointer-events: none;
  user-select: none;
}

/* 节点 */
.flow-node {
  position: absolute;
  width: 160px;
  background: #fff;
  border: 1px solid #e0e0e0;
  border-radius: 10px;
  box-shadow: 0 3px 10px rgba(0, 21, 41, 0.1);
  cursor: move;
  z-index: 2;
  user-select: none;
  transition: box-shadow 0.2s, border-color 0.2s, transform 0.1s;
}
.flow-node:hover {
  box-shadow: 0 6px 20px rgba(0, 21, 41, 0.16);
  border-color: #c0c4cc;
}
.flow-node.is-selected {
  border-color: #409EFF;
  box-shadow: 0 0 0 2px rgba(64, 158, 255, 0.25), 0 6px 20px rgba(64, 158, 255, 0.18);
}
.flow-node.is-running {
  border-color: #52c41a;
