.node-header.blue { background: linear-gradient(135deg, #409EFF, #69b1ff); }
.node-header.purple { background: linear-gradient(135deg, #722ed1, #9254de); }
.node-header.orange { background: linear-gradient(135deg, #fa8c16, #ffa940); }
.node-header.cyan { background: linear-gradient(135deg, #13c2c2, #36cfc9); }
.node-header.red { background: linear-gradient(135deg, #f5222d, #ff4d4f); }
.node-icon {
  font-size: 14px;
}
.node-title {
  flex: 1;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.node-del {
  cursor: pointer;
  font-size: 12px;
  opacity: 0.7;
}
.node-del:hover {
  opacity: 1;
}
.node-body {
  padding: 9px 10px;
}
.node-desc {
  font-size: 12px;
  color: #666;
  line-height: 1.4;
  margin-bottom: 6px;
}
.node-config {
  border-top: 1px dashed #eee;
  padding-top: 6px;
}
.config-item {
  font-size: 11px;
