}
.config-key {
  color: #666;
  flex-shrink: 0;
}
.config-val {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 连接点 */
.port {
  position: absolute;
  width: 13px;
  height: 13px;
  border-radius: 50%;
